"المساعد يبحث في ملفات مشروعك وملفاتك أولًا، ثم المكتبة العامة":"The assistant searches your project's files and your files first, then the public library",
"المساعد لا يستعمل ملفاتك — المكتبة العامة فقط":"The assistant does not use your files — the public library only",
"✓ متصل الآن بـ {0} · {1} — المحادثة تفهم مشروعك وملفاتك وتستطيع تعديله (بمعاينة قبل التطبيق).":"✓ Now connected to {0} · {1} — the chat understands your project and files and can change it (with a preview before applying).",
"المزوّد مطفأ — يعمل «المخطّط المدمج» فقط.":"The provider is off — only the «built-in planner» runs.",
"متصل بـ {0} · {1} — الخطة والكود من النموذج، مع فحص حقيقي للأصول والـAPI قبل التطبيق.":"Connected to {0} · {1} — the plan and the code come from the model, with a real check of assets and the API before applying.",
"الذكاء المجاني متاح لمن سجّل الدخول بحساب Google — سجّل الدخول وسيعمل وحده. حتى ذلك الحين يعمل «المخطّط المدمج».":"The free AI is available to those signed in with Google — sign in and it works by itself. Until then the «built-in planner» runs.",
"لا يوجد مزوّد AI: يعمل «المخطّط المدمج» — يتعرّف على كلمات مفتاحية ويبني أنظمة جاهزة حقيقية. هذا ليس ذكاءً اصطناعيًا؛ لطلبات حرّة صِلْ مزوّدًا من ⚙.":"No AI provider: the «built-in planner» runs — it recognises keywords and builds real ready systems. This is not AI; for free-form requests connect a provider from ⚙.",
"قل لي ما نوع اللعبة التي تريدها وسأخطّط لها وأبنيها وأختبرها. تستطيع إيقافي في أي لحظة، ولكل تغيير نقطة رجوع.":"Tell me what kind of game you want and I will plan it, build it and test it. You can stop me at any moment, and every change has a restore point.",
"اطلب ما تريد. سأقرأ مشروعك أولًا، ثم أضع خطة، ثم أنفّذ وأبني وأختبر وأصلح.":"Ask for what you want. I will read your project first, then make a plan, then carry it out, build, test and fix.",
"⚙ ربط نموذج ذكاء اصطناعي":"⚙ Connect an AI model",
"أضفت طلبك إلى الطابور.":"I added your request to the queue.",
"هذه هي الملفات التي يستطيع المساعد استعمالها في هذا المشروع. يرى بياناتها فقط (الاسم والنوع والأبعاد) — ويُحمَّل الملف نفسه عندما يضعه في المشهد. ملفات Google Drive الأخرى وملفات الآخرين الخاصة لا يراها أبدًا.":"These are the files the assistant can use in this project. It sees only their data (name, type and size) — the file itself loads when it places it in the scene. It never sees your other Google Drive files or other people's private files.",
"أصول يستطيع المساعد استعمالها":"Assets the assistant can use",
"«استخدم أصول مشروعي» مطفأ — المساعد يبحث في المكتبة العامة فقط.":"«Use my project's assets» is off — the assistant searches the public library only.",
