"بدون مزوّد يعمل المخطّط المدمج: يفهم الطلبات الشائعة ويبني أنظمة حقيقية، لكنه لا يفهم أي وصف حر ولا يحاور.":"Without a provider the built-in planner runs: it understands common requests and builds real systems, but it understands no free description and does not chat.",
