"{0}الخطة المجانية تسمح بعدد محدود من الرموز في الدقيقة. جرّب نموذجًا حدّه أكبر (مثل llama-3.3-70b-versatile في Groq)، أو ابدأ محادثة جديدة، أو انتظر دقيقة.":"{0}The free plan allows a limited number of tokens per minute. Try a model with a bigger limit (like llama-3.3-70b-versatile on Groq), start a new chat, or wait a minute.",
