"NEXUS AI — مجاني":"NEXUS AI — free",
"ذكاء اصطناعي مجاني يقدّمه صاحب المنصة لكل من سجّل الدخول بحساب Google. اختر النموذج فقط — المفاتيح على خادم الموقع ولا تظهر لأحد. إذا انتهى حدّ مفتاح ينتقل وحده إلى التالي، ثم إلى النموذج الآخر.":"A free AI offered by the platform's owner to everyone signed in with Google. Just choose the model — the keys are on the site's server and nobody sees them. When a key's limit runs out it moves to the next one by itself, then to the other model.",
"سريع جدًا. المفتاح مجاني من لوحة Groq ويبدأ بـ gsk_.":"Very fast. The key is free from the Groq console and starts with gsk_.",
"نماذج Grok من xAI. المفتاح يبدأ بـ xai-.":"Grok models from xAI. The key starts with xai-.",
"يحتاج ترويسة الوصول المباشر من المتصفح؛ وهي مضافة تلقائيًا.":"Needs the direct-browser-access header; it is added automatically.",
"المفتاح من Google AI Studio (يبدأ بـ AIza أو AQ.).":"The key from Google AI Studio (starts with AIza or AQ.).",
"نموذج محلي (Ollama / LM Studio)":"Local model (Ollama / LM Studio)",
"يعمل بلا إنترنت إذا كان الخادم يعمل على جهازك ويسمح بـCORS.":"Works without internet if the server runs on your device and allows CORS.",
"أي موقع (Base URL)":"Any site (Base URL)",
"أي موقع متوافق مع OpenAI (مثل cleanapis): الصق رابطه الذي ينتهي بـ /v1 ثم مفتاحه — تظهر نماذجه لتختار منها، ويُختبر بطلب حقيقي قبل الاستعمال.":"Any OpenAI-compatible site (like cleanapis): paste its address ending in /v1, then its key — its models show for you to choose from, and it is tested with a real request before use.",
"لم يُحفظ الإعداد: هذا المتصفح لا يسمح بالحفظ (وضع التصفّح الخاص أو ذاكرة ممتلئة). افتح الموقع في متصفح عادي مثل Chrome.":"The setting was not saved: this browser does not allow saving (private browsing or full storage). Open the site in a normal browser like Chrome.",
"دالة الذكاء تعمل على خادم الموقع لكن بلا مفاتيح. صاحب الموقع يضع GEMINI_KEYS و GROQ_KEYS في Netlify ← Site configuration ← Environment variables، ثم Deploys ← Trigger deploy.":"The AI function runs on the site's server, but without keys. The site owner puts GEMINI_KEYS and GROQ_KEYS in Netlify ← Site configuration ← Environment variables, then Deploys ← Trigger deploy.",
"خادم الموقع لا يشغّل دالة الذكاء (netlify/edge-functions/ai.js) — غالبًا لأن الموقع رُفع بالسحب والإفلات، والدوال لا تعمل هكذا. صاحب الموقع يربطه بـ GitHub في Netlify (Base directory = nexus) ثم يضع المفاتيح في Environment variables.":"The site's server does not run the AI function (netlify/edge-functions/ai.js) — most likely because the site was uploaded by drag-and-drop, and functions do not run that way. The site owner links it to GitHub in Netlify (Base directory = nexus), then puts the keys in Environment variables.",
"تعذّر الوصول إلى الخادم (Network / CORS)":"Could not reach the server (Network / CORS)",
"إما أن الشبكة مقطوعة، أو أن المزوّد يمنع الطلبات المباشرة من المتصفح (CORS). المتصفح لا يكشف أيّهما — جرّب من شبكة أخرى، أو استخدم وسيطًا (proxy) خاصًا بك كمزوّد مخصّص.":"Either the network is down, or the provider blocks direct requests from the browser (CORS). The browser does not reveal which — try another network, or use your own proxy as a custom provider.",
