"بلا مزوّد تعمل أوامر المشهد والأصول فعليًا: «أضف سيارة بجانب المبنى»، «اجعلها أكبر»، «ضعها خلف المنزل»، «حلل لعبتي»، «تراجع». أما المحادثة الحرّة وتعديل الكود بطلب حر فتحتاج نموذجًا.":"Without a provider the scene and asset commands really run: «Add a car next to the building», «Make it bigger», «Put it behind the house», «Analyse my game», «Undo». Free chat and changing code on a free request need a model.",
