"الصندوق مسجّل باسم {0}. تستطيع استعمال الذكاء المجاني، أو إضافة مفتاحك الخاص من «مزوّدو الذكاء الاصطناعي».":"The box is registered to {0}. You can use the free AI, or add your own key from «AI providers».",
