"المفاتيح المحفوظة ({0})":"Saved keys ({0})",
"حذف المفتاح {0} {1}؟":"Delete key {0} {1}?",
"وصل المتغيّر ({0} حرفًا)، لكن قيمته ليست محتوى الملف. لا تلصق اسم الملف ولا رابطه:":"The variable arrived ({0} characters), but its value isn't the file's content. Don't paste the file name or its link:",
