"العربية · English · हिन्दी":"Arabic · English · हिन्दी",
"سجّل الدخول بحساب Google أولًا":"Sign in with a Google account first",
"ذكاء مجاني لكل من يستعمل موقعك":"Free AI for everyone who uses your site",
"ضع هنا مفاتيح Gemini (Google AI Studio) أو Groq أو OpenRouter أو Claude (Anthropic — مدفوع، ولا يستعمله «auto» إلا إذا اختار اللاعب نموذج Claude أو ANTHROPIC_AUTO=1) مرة واحدة. تُحفظ على خادم الموقع فقط: لا يراها أحد، ولا تُرسل إلى أي صفحة — ولا حتى إليك بعد الحفظ (يظهر آخر 4 أحرف فقط). كل من ليس لديه مفتاح يحصل على الذكاء المجاني ويختار النموذج فقط. إذا انتهى حدّ مفتاح يُستعمل التالي تلقائيًا، ثم Groq، ثم «غير متاح الآن».":"Put Gemini (Google AI Studio), Groq, OpenRouter or Claude keys here once (Anthropic — paid; «auto» only uses it if the player picks a Claude model or ANTHROPIC_AUTO=1). They're saved on the site's server only: nobody sees them, and they're never sent to any page — not even to you after saving (only the last 4 characters show). Everyone without a key gets the free AI and just picks the model. If a key hits its limit the next one is used automatically, then Groq, then «not available now».",
"أو: مفتاح لي أنا فقط (في هذا المتصفح)":"Or: a key just for me (in this browser)",
"🔑 مفاتيح الذكاء المجاني":"🔑 Free AI keys",
"أتحقّق من خادم الموقع…":"Checking the site server…",
"⚠ خادم الموقع لا يعمل بعد":"⚠ The site server isn't running yet",
"المفاتيح تُحفظ على خادم الموقع (دالة Netlify)، والدوال لا تعمل عندما يُرفع الموقع بالسحب والإفلات. خطوة واحدة في Netlify:":"Keys are saved on the site server (a Netlify function), and functions don't run when the site is uploaded by drag and drop. One step in Netlify:",
"اختر مستودع GitHub، واكتب في Base directory: nexus":"Choose the GitHub repository, and type in Base directory: nexus",
