"إلى أن يعمل الصندوق: الصق مفاتيحك هنا، وسأجهّز لك نصًّا واحدًا تلصقه في Netlify — يعمل فورًا بعد Trigger deploy، ولا يرى أحد المفاتيح. النص يُصنع على جهازك ولا يُرسل إلى أي مكان.":"Until the box works: paste your keys here, and I'll prepare a single text for you to paste into Netlify — it works right after Trigger deploy, and nobody sees the keys. The text is made on your device and isn't sent anywhere.",
