"على موقع Netlify مربوط بـ GitHub يعمل الصندوق وحده (مخزن Netlify Blobs) — بعد أن تُنشر هذه النسخة الجديدة من NEXUS: Deploys ← Trigger deploy ← Deploy site. إن بقيت هذه الرسالة بعد النشر، فالطريق البديل مرة واحدة:":"On a Netlify site linked to GitHub the box works on its own (Netlify Blobs store) — after this new version of NEXUS is deployed: Deploys → Trigger deploy → Deploy site. If this message remains after deploying, the one-time alternative route:",
