"التبرّع يحتاج اتصال الموقع بالسحابة":"Donating needs the site connected to the cloud",
"سجّل الدخول بحساب (Google أو البريد) أولًا":"Sign in with an account (Google or email) first",
"هذا المفتاح في المجمّع من قبل — لا يُتبرَّع بالمفتاح نفسه مرتين.":"This key is already in the pool — the same key can't be donated twice.",
"هذا لا يشبه مفتاح API":"This doesn't look like an API key",
"💎 متبرّع قوي — شارة في ملفك ونقاط الإعلانات ×2 ما دام مفتاحك يعمل":"💎 Strong donor — a badge on your profile and ad points ×2 as long as your key works",
"🤝 متبرّع — شكرًا! (مفتاح يعمل بنماذج قوية يمنح 💎 ونقاط إعلانات ×2)":"🤝 Donor — thank you! (a key that works with strong models gives 💎 and ad points ×2)",
"غير منشورة أو لا يمكن الوصول إليها":"Not deployed or unreachable",
"لا توجد رسالة":"No message",
"تعذّر الوصول إلى processRequest — الدالة غير منشورة (تحتاج خطة Blaze) أو الشبكة مقطوعة":"Couldn't reach processRequest — the function isn't deployed (needs the Blaze plan) or the network is down",
"تبرّع بمفتاح Gemini أو Groq أو OpenRouter أو Claude — أو مفتاح أي موقع متوافق مع OpenAI (مع Base URL) — ليبقى الذكاء المجاني في هذا الموقع (ومجلس الذكاء لمشتركي Pro) يعمل للجميع.":"Donate a Gemini, Groq, OpenRouter or Claude key — or a key for any OpenAI-compatible site (with its Base URL) — to keep the free AI on this site (and the AI Council for Pro subscribers) working for everyone.",
"🔒 ماذا يحدث لمفتاحك؟":"🔒 What happens to your key?",
"• يُكتب مرة واحدة في قاعدة بيانات الموقع، ولا يستطيع أحد قراءته بعدها: لا الزوار ولا البوتات ولا أنت (هذه الصفحة تحفظ آخر 4 أحرف فقط).":"• It's written once to the site's database, and nobody can read it afterwards: not visitors, not bots, not you (this page keeps only the last 4 characters).",
"• يستعمله خادم الموقع وحده ليجيب الذكاء المجاني؛ لا يصل إلى أي متصفح في أي رد أو رسالة خطأ.":"• Only the site's server uses it to answer with the free AI; it never reaches any browser in any response or error message.",
"• إن رفضه المزوّد يُعطَّل وحده، وإن وصل حدّه يرتاح ثم يعود. تسحبه متى شئت.":"• If the provider rejects it, it's disabled by itself, and if it hits its limit it rests and then comes back. You can withdraw it whenever you want.",
"• المفتاح نفسه لا يُقبل مرتين (تُحفظ بصمته SHA-256، لا المفتاح). يختبره الخادم بطلب حقيقي: إن كان يعمل بنماذج قوية تصير «💎 متبرّعًا قويًا» — شارة في ملفك ونقاط الإعلانات ×2 ما دام مفتاحك يعمل؛ وإلا «🤝 متبرّع».":"• The same key isn't accepted twice (its SHA-256 fingerprint is saved, not the key). The server tests it with a real request: if it works with strong models you become a «💎 strong donor» — a badge on your profile and ad points ×2 as long as your key works; otherwise «🤝 donor».",
"• يُستعمل بقدر: في مجلس الذكاء يخدم مفتاحك المتبرَّع به نموذجًا واحدًا في كل مرة (لا طلبات متوازية عليه)، والمفتاح الذي يصل حدّه يرتاح حتى يسمح المزوّد. صاحب الموقع يستطيع إبعاد المفاتيح المتبرَّع بها عن المجلس (COUNCIL_USE_DONATED=0).":"• It's used in moderation: in the AI Council your donated key serves one model at a time (no parallel requests on it), and a key that hits its limit rests until the provider allows it. The site owner can keep donated keys out of the Council (COUNCIL_USE_DONATED=0).",
"• مفتاح Claude (Anthropic) مدفوع: كل طلب يُخصم من رصيدك عند Anthropic — لا تتبرّع به إلا إن كنت تقبل ذلك، ويمكنك سحبه متى شئت. OpenRouter: النماذج المجانية فقط.":"• A Claude (Anthropic) key is paid: every request is charged to your Anthropic balance — only donate it if you accept that, and you can withdraw it whenever you want. OpenRouter: free models only.",
"• مالك الموقع يصل إلى قاعدة البيانات من لوحة Firebase — تبرّع لموقع تثق بصاحبه، وتأكّد أن شروط مزوّدك تسمح بمشاركة المفتاح.":"• The site owner can reach the database from the Firebase console — donate to a site whose owner you trust, and make sure your provider's terms allow sharing the key.",
"الصق المفتاح هنا (gsk_… أو AIza… أو AQ.… أو sk-or-… أو sk-ant-…)":"Paste the key here (gsk_… or AIza… or AQ.… or sk-or-… or sk-ant-…)",
"المفتاح ملكي، وأسمح باستعماله للذكاء المجاني في هذا الموقع، وأعرف أنني أستطيع سحبه متى شئت.":"The key is mine, I allow it to be used for the free AI on this site, and I know I can withdraw it whenever I want.",
