"نموذج واحد لكل مهمة.":"One model per task.",
"NEXUS يقرّر كم نموذجًا تحتاج المهمة: البسيطة (تحية، سؤال قصير، تعديل صغير) بنموذج واحد، والكبيرة (لعبة كاملة، أنظمة كثيرة) حتى 4 — أقل تكلفة وانتظار.":"NEXUS decides how many models a task needs: simple ones (a greeting, a short question, a small edit) with one model, and big ones (a full game, many systems) with up to 4 — less cost and waiting.",
"حتى 4 نماذج في كل مهمة يرسلها المساعد — أبطأ ويستهلك طلبات أكثر.":"Up to 4 models on every task the assistant sends — slower and uses more requests.",
