"Multi-AI Council من مزايا NEXUS Pro — تحقّق الخادم من حسابك وأجاب نموذج واحد.":"Multi-AI Council is a NEXUS Pro feature — the server checked your account and one model answered.",
"لا يستطيع خادم الموقع التحقق من Pro الآن — أجاب نموذج واحد.":"The site server can't verify Pro right now — one model answered.",
"طلبات اليوم المتبقية لا تكفي لكل النماذج — مجلس أصغر.":"Today's remaining requests aren't enough for all the models — a smaller Council.",
"حدّ الخادم للنماذج في الطلب الواحد — مجلس أصغر.":"The server's limit on models per request — a smaller Council.",
"Synthesis · المراجعة والدمج":"Synthesis · review and merge",
"لم يُشغَّل":"Didn't run",
"نموذج واحد":"One model",
"بعض النماذج لم تُجب":"Some models didn't answer",
"✓ Final result ready · النتيجة النهائية جاهزة":"✓ Final result ready",
"أجاب نموذج واحد":"One model answered",
"Multi-AI collaboration: عدة نماذج عملت معًا على هذه النتيجة، كلٌّ بدوره، ثم راجع أحدها كل المساهمات وكتب النتيجة النهائية أعلاه. ليس نموذجًا جديدًا — وهذه مساهمة كل نموذج كما كتبها.":"Multi-AI collaboration: several models worked together on this result, each in its role, then one of them reviewed all the contributions and wrote the final result above. It isn't a new model — and here is each model's contribution as it wrote it.",
"بعض النماذج لم تُجب — استُعمل ما توفّر.":"Some models didn't answer — what was available was used.",
"· مفتاحك":"· your key",
"فشل":"Failed",
"لم يُجب":"Didn't answer",
"🧠 مجلس الذكاء · Multi-AI Council":"🧠 AI Council · Multi-AI Council",
"• حتى 4 نماذج ذكاء اصطناعي تعمل على المهمة الواحدة، كلٌّ بدوره: الخطة، الأصول الحقيقية، الكود، المراجعة.":"• Up to 4 AI models work on one task, each in its role: the plan, the real assets, the code, the review.",
"• ثم يراجع أحدها كل النتائج ويكتب نتيجة نهائية واحدة — تُنفَّذ في مشروعك كما تُنفَّذ نتيجة نموذج واحد: معاينة ثم APPLY، أصول حقيقية فقط، وتراجع بخطوة واحدة.":"• Then one of them reviews all the results and writes one final result — applied to your project just like a single model's result: preview, then APPLY, real assets only, and one-step undo.",
"• إذا فشل نموذج يكمل الباقون، وإذا فشل الدمج يكمله نموذج آخر.":"• If a model fails the others continue, and if the merge fails another model completes it.",
"• هذا تعاون بين نماذج موجودة، وليس نموذجًا جديدًا ولا «أقوى من Claude».":"• This is collaboration between existing models, not a new model and not «stronger than Claude».",
"أسأل الخادم عن حسابك…":"Asking the server about your account…",
"🔒 سجّل الدخول أولًا":"🔒 Sign in first",
"المجلس يعمل عبر الذكاء المجاني في الموقع، لأصحاب الحسابات.":"The Council works through the site's free AI, for account holders.",
"مجلس الذكاء لأصحاب الحسابات.":"The AI Council is for account holders.",
"⚪ المجلس غير متاح على هذا الموقع":"⚪ The Council isn't available on this site",
"خادم الموقع لا يجيب الآن — جرّب بعد قليل.":"The site server isn't answering right now — try again shortly.",
"⚪ صاحب الموقع أوقف المجلس أو لم يضع مفاتيح بعد":"⚪ The site owner turned the Council off or hasn't added keys yet",
"الخادم يتحقّق من اشتراكك في كل طلب — الصفحة لا تقرّر ذلك.":"The server checks your subscription on every request — the page doesn't decide that.",
"حسابك مجاني: نموذج واحد لكل مهمة (Single AI).":"Your account is free: one model per task (Single AI).",
"Multi-AI Council من مزايا NEXUS Pro. الخادم يعطي الحساب المجاني نموذجًا واحدًا مهما أُرسل من المتصفح.":"Multi-AI Council is a NEXUS Pro feature. The server gives a free account one model whatever the browser sends.",
"لا يستطيع خادم الموقع التحقق من Pro الآن (يحتاج FIREBASE_SERVICE_ACCOUNT) — نموذج واحد فقط.":"The site server can't verify Pro right now (it needs FIREBASE_SERVICE_ACCOUNT) — one model only.",
"⭐ اشترك في NEXUS Pro":"⭐ Subscribe to NEXUS Pro",
"الوضع":"Mode",
"— موصى به":"— recommended",
"بلا اختيار: النموذج الذي تستعمله يقود، و«NEXUS · auto» للبقية (يوزّعها الخادم على مزوّدين مختلفين). نماذج مفاتيحك الخاصة تعمل من متصفحك — مفاتيحك لا تغادره.":"No choice: the model you use leads, and «NEXUS · auto» for the rest (the server spreads them over different providers). Your own keys' models run from your browser — your keys never leave it.",
