"(حسابك: 1)":"(your account: 1)",
"يضبطها صاحب الموقع على خادمه (COUNCIL_* في Netlify)، والمتصفح لا يستطيع تجاوزها. كل استدعاء نموذج يُحسب طلبًا من طلبات ذكاء اليوم، وما لم يُستعمل يُعاد.":"The site owner sets them on their server (COUNCIL_* in Netlify), and the browser can't bypass them. Every model call counts as one of today's AI requests, and whatever isn't used is returned.",
"نموذج واحد لكل مهمة — متاح للجميع.":"One model per task — available to everyone.",
"يختار NEXUS عدد النماذج تلقائيًا حسب تعقيد المهمة (نموذج واحد للمهمة البسيطة، حتى 4 للكبيرة).":"NEXUS picks the number of models automatically based on the task's complexity (one model for a simple task, up to 4 for a big one).",
"اختر حتى 4 نماذج — كلها تعمل على كل مهمة، ثم نتيجة واحدة مدمجة.":"Choose up to 4 models — all of them work on every task, then one merged result.",
"(الافتراضي لـ Pro)":"(Pro default)",
"حسابك مجاني: Single AI. الخادم يتحقّق من الاشتراك في كل طلب — تغيير الصفحة لا يفتح أكثر من نموذج.":"Your account is free: Single AI. The server checks the subscription on every request — changing the page doesn't unlock more than one model.",
"لا يستطيع خادم الموقع التحقق من Pro الآن — نموذج واحد فقط.":"The site server can't verify Pro right now — one model only.",
"كل إعدادات المجلس (نموذج الدمج، حدود الخادم)…":"All Council settings (merge model, server limits)…",
