"لصاحب المنصة فقط. الصق هنا «firebaseConfig» من: Firebase Console ← ⚙ Project settings ← General ← Your apps ← Web app ← Config. لا يُحفظ شيء على هذا الجهاز. الناتج ملف index.html جاهز ترفعه إلى Netlify بدل الحالي — فيستخدم كل الزوار نفس المشروع.":"For the platform owner only. Paste the «firebaseConfig» here from: Firebase Console → ⚙ Project settings → General → Your apps → Web app → Config. Nothing is saved on this device. The output is a ready index.html file you upload to Netlify in place of the current one — so all visitors use the same project.",
