"يحذف النسخ المؤقتة على هذا الجهاز فقط (المجسمات في الذاكرة، أيقونات الأصول، نسخ العمل دون إنترنت). الأصول نفسها — سجلّاتها في Firebase وملفاتها في Drive — لا تُمس، وتُعاد أيقوناتها منها":"Deletes the temporary copies on this device only (models in memory, asset icons, offline work copies). The assets themselves — their records in Firebase and their files in Drive — aren't touched, and their icons are restored from them",
"الأصول ≠ الكود":"Assets ≠ code",
"• الأصول (GLB/صور/صوت) بيانات فقط ولا تُنفَّذ أبدًا؛ لا يُقبل رفع ملفات سكربت كأصول. • كود مطوّر آخر لا يعمل إلا بموافقتك الصريحة، ويمكنك قراءته قبل التشغيل. • كود الآخرين (ألعابهم المنشورة وكل مشروع فيه فريق) يعمل في صندوق معزول (iframe sandbox) بمصدر مجهول: لا يصل إلى جلسة دخولك ولا تخزين الموقع ولا مفاتيح AI ولا Firebase — فقط عبر جسر يسمح بغرف اللعبة وحفظها وأصولها المقروءة. • كودك أنت في مشروعك الفردي يعمل داخل الصفحة كما كان (التقييد هناك حاجز سلامة).":"• Assets (GLB/images/sound) are data only and are never executed; script files aren't accepted as assets. • Another developer's code only runs with your explicit consent, and you can read it before running. • Others' code (their published games and every project with a team) runs in an isolated box (iframe sandbox) with an opaque origin: it can't reach your sign-in session, the site's storage, AI keys or Firebase — only through a bridge that allows game rooms, saves and readable assets. • Your own code in your solo project runs inside the page as before (the restriction there is a safety barrier).",
"قواعد واحدة للمنصة كلها. العدادات والملكية والخصوصية تُفرض على الخادم لا في المتصفح.":"One set of rules for the whole platform. Counters, ownership and privacy are enforced on the server, not in the browser.",
